-- CAN Algebra I Week 01; synthetic only. Never apply to production learner records.
-- Run all blocks as one transaction, after SET LOCAL can.seed_authorized=algebra1-week01.
-- Every source publication remains immutable; existing class pointer is explicitly upgraded.
DO $gate$ BEGIN
IF current_setting('can.seed_authorized',true) IS DISTINCT FROM 'algebra1-week01' THEN RAISE EXCEPTION 'Guarded Algebra I demo deployment requires explicit session setting'; END IF;
IF NOT EXISTS(SELECT 1 FROM organizations WHERE id='f1000000-0000-4000-8000-000000000002' AND slug='can-synthetic-demo' AND metadata->>'synthetic'='true') THEN RAISE EXCEPTION 'Not the synthetic ValorSchool org'; END IF;
IF NOT EXISTS(SELECT 1 FROM sections s WHERE s.id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND s.program_id='f1000000-0000-4000-8000-000000000004' AND s.code='CAN-ALG1'
 AND s.course_template_version_id IN ('bf36382c-1a56-484b-72e1-a037d3203626',md5('can-core-version:CAN-ALG1:week01:v2')::uuid) AND s.metadata->>'synthetic'='true')
THEN RAISE EXCEPTION 'Algebra I class is not the expected synthetic pilot version'; END IF;
IF NOT EXISTS(SELECT 1 FROM curriculum_adoptions a WHERE a.program_id='f1000000-0000-4000-8000-000000000004' AND a.pack_id='f9260000-0000-4000-8000-000000000001'
 AND a.pack_version_id IN ('f9260000-0000-4000-8000-000000000002',md5('can-core-pack-version:week01:v2')::uuid) AND a.status='active') THEN RAISE EXCEPTION 'Expected pack adoption not found'; END IF;
IF EXISTS(SELECT 1 FROM enrollments e WHERE e.section_id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND (e.metadata->>'synthetic') IS DISTINCT FROM 'true')
THEN RAISE EXCEPTION 'Found nonsynthetic student in class: do not reassign'; END IF;
IF EXISTS(SELECT 1 FROM curriculum_overlays ov WHERE ov.course_template_version_id='bf36382c-1a56-484b-72e1-a037d3203626' AND ov.program_id='f1000000-0000-4000-8000-000000000004')
THEN RAISE EXCEPTION 'Source version has site/class overlays requiring explicit migration'; END IF;
IF NOT EXISTS(SELECT 1 FROM section_teachers st JOIN account_person_grants g ON g.person_id=st.person_id JOIN access_accounts a ON a.id=g.account_id
 WHERE st.section_id='7b6eb18e-8191-fbd5-bc2d-cd860e6b26a0' AND g.role='teacher' AND a.email_normalized='riley.teacher@valorschool.demo') THEN RAISE EXCEPTION 'Demo teacher missing'; END IF;
END $gate$;
-- CAN_STATEMENT_BREAK
INSERT INTO course_template_versions(id,course_template_id,version,status,curriculum,published_at)
SELECT md5('can-core-version:CAN-ALG1:week01:v2')::uuid,v.course_template_id,2,'published',
jsonb_set(jsonb_set(jsonb_set(v.curriculum,'{learning,modules}',
 COALESCE(v.curriculum->'learning'->'modules','[]'::jsonb)||jsonb_build_array('{"id":"algebra1-u01","title":"Unit 1 · Expressions, Equations, and Inequalities","lessons":[{"id":"u01-d01","title":"Day 1 · Expressions and Equivalent Forms","body":"ALGEBRA I • UNIT 1 • DAY 1 OF 5 • 55 MINUTES\nEssential question: What makes two algebraic expressions equivalent?\nLearning targets: I can distinguish expressions from equations; evaluate expressions using substitution; use distribution and collecting like terms to rewrite expressions. Standards: HSA-SSE.A.1; HSA-REI.A.1. Prerequisites: signed-number operations and the order of operations.\n\nLAUNCH (5 min)\nA school club orders 3 shirts for each of n volunteers, plus 6 extras. Two students represent the shirts as 3n + 6 and 3(n + 2). Try n = 4 and n = 10. Are the expressions equal for every n? Explain using distribution, not only a calculator.\n\nEXPLICIT INSTRUCTION (12 min)\nA variable represents a quantity. An expression such as 4x - 5 has no equality claim; an equation such as 4x - 5 = 19 asserts equality. Terms are quantities joined by addition or subtraction. Like terms share the same variable part (5x and -2x), so 5x - 2x + 7 = 3x + 7. Distribute: 2(3x - 4) = 6x - 8. The expressions 2(3x - 4) and 6x - 8 are equivalent for every x.\nWORKED EXAMPLE: Simplify 4(2x - 3) - (x + 5).\n1. Distribute: 8x - 12 - x - 5.\n2. Combine like terms: 7x - 17.\n3. Check with x = 2: original 4(4 - 3) - (2 + 5) = 4 - 7 = -3; simplified 14 - 17 = -3.\nChecking one input helps catch errors; using distribution and like terms establishes equivalence.\n\nGUIDED PRACTICE (12 min)\nA. Evaluate 2a + 3b for a = -2 and b = 5; show substituted expression first.\nB. Simplify 5(y + 2) - 3y.\nC. Explain why 4x + 4 cannot be simplified to 8x.\nCompare reasoning with a peer or teacher; explicitly name the equality property used.\n\nINDEPENDENT PRACTICE (16 min)\n1. Evaluate 3x² - 2x for x = -2.\n2. Expand and simplify 3(2p - 5) + 4p.\n3. Write two different equivalent expressions for the cost of n $8 tickets with a one-time $6 fee.\n4. Error analysis: A student rewrites 2(x + 5) as 2x + 5. Identify the mistake and fix it.\n5. Challenge: Show algebraically that (x + 3) + (2x - 4) equals 3x - 1 for every real x.\n\nEXIT TICKET (10 min)\nSimplify 2(3k - 4) + k and explain each step. Then write one sentence describing the difference between an expression and an equation.\nTurn in the exit ticket for formative feedback; it is not a grade from lesson completion alone.\n\nSELF-CHECK AND SUPPORT\nFor guided practice: A = 11; B = 2y + 10; C combines unlike terms. If you distributed to obtain 2x + 5, revisit how multiplication applies to every term inside parentheses. Extension: design two equivalent formulas for a school fundraiser.","resources":[],"learningTargets":["I can distinguish expressions from equations","evaluate expressions using substitution","use distribution and collecting like terms to rewrite expressions. Standards: HSA-SSE.A.1","HSA-REI.A.1. Prerequisites: signed-number operations and the order of operations."],"standards":["A-SSE.1","A-REI.1"],"estimatedMinutes":55,"activities":[{"id":"u01-d01-a1","kind":"launch","title":"Launch","estimatedMinutes":5,"evidence":"practice","instructions":"Essential question: What makes two algebraic expressions equivalent?\n\nA school club orders 3 shirts for each of n volunteers, plus 6 extras. Two students represent the shirts as 3n + 6 and 3(n + 2). Try n = 4 and n = 10. Are the expressions equal for every n? Explain using distribution, not only a calculator."},{"id":"u01-d01-a2","kind":"instruction","title":"Explicit Instruction","estimatedMinutes":12,"evidence":"practice","instructions":"A variable represents a quantity. An expression such as 4x - 5 has no equality claim; an equation such as 4x - 5 = 19 asserts equality. Terms are quantities joined by addition or subtraction. Like terms share the same variable part (5x and -2x), so 5x - 2x + 7 = 3x + 7. Distribute: 2(3x - 4) = 6x - 8. The expressions 2(3x - 4) and 6x - 8 are equivalent for every x.\nWORKED EXAMPLE: Simplify 4(2x - 3) - (x + 5).\n1. Distribute: 8x - 12 - x - 5.\n2. Combine like terms: 7x - 17.\n3. Check with x = 2: original 4(4 - 3) - (2 + 5) = 4 - 7 = -3; simplified 14 - 17 = -3.\nChecking one input helps catch errors; using distribution and like terms establishes equivalence."},{"id":"u01-d01-a3","kind":"guided_practice","title":"Guided Practice","estimatedMinutes":12,"evidence":"practice","instructions":"A. Evaluate 2a + 3b for a = -2 and b = 5; show substituted expression first.\nB. Simplify 5(y + 2) - 3y.\nC. Explain why 4x + 4 cannot be simplified to 8x.\nCompare reasoning with a peer or teacher; explicitly name the equality property used."},{"id":"u01-d01-a4","kind":"independent_practice","title":"Independent Practice","estimatedMinutes":16,"evidence":"practice","instructions":"1. Evaluate 3x² - 2x for x = -2.\n2. Expand and simplify 3(2p - 5) + 4p.\n3. Write two different equivalent expressions for the cost of n $8 tickets with a one-time $6 fee.\n4. Error analysis: A student rewrites 2(x + 5) as 2x + 5. Identify the mistake and fix it.\n5. Challenge: Show algebraically that (x + 3) + (2x - 4) equals 3x - 1 for every real x."},{"id":"u01-d01-a5","kind":"exit_ticket","title":"Exit Ticket","estimatedMinutes":10,"evidence":"teacher_review","instructions":"Simplify 2(3k - 4) + k and explain each step. Then write one sentence describing the difference between an expression and an equation.\nTurn in the exit ticket for formative feedback; it is not a grade from lesson completion alone."},{"id":"u01-d01-a6","kind":"self_check","title":"Self-Check And Support","evidence":"practice","instructions":"For guided practice: A = 11; B = 2y + 10; C combines unlike terms. If you distributed to obtain 2x + 5, revisit how multiplication applies to every term inside parentheses. Extension: design two equivalent formulas for a school fundraiser."}]},{"id":"u01-d02","title":"Day 2 · Solving Equations with Equality","body":"ALGEBRA I • UNIT 1 • DAY 2 OF 5 • 55 MINUTES\nEssential question: Why does doing the same operation to both sides preserve equality?\nLearning targets: I can solve one- and two-step equations, justify each transformation, and check solutions. Standards: HSA-REI.A.1, HSA-REI.B.3.\nMaterials: pencil, scratch paper or equation editor. Prior knowledge: inverse operations.\n\nLAUNCH (6 min)\nA balance scale holds a sealed bag and 7 blocks on the left, 19 blocks on the right. What is the mass of the bag in block units? Write b + 7 = 19. Explain what happens if we remove 7 blocks from both sides.\n\nMINI-LESSON (12 min)\nAn equation gives two equal quantities. Subtracting, adding, multiplying or dividing by the same nonzero quantity on both sides preserves the solution set. To isolate x in 3x + 5 = 20:\n1. Subtract 5 on each side: 3x = 15.\n2. Divide each side by 3: x = 5.\n3. Substitute into the original: 3(5) + 5 = 20. Both sides equal 20.\nA calculation without a check can conceal sign mistakes. In -2x - 6 = 10, add 6 then divide by -2 to get x = -8. Substitute: -2(-8) - 6 = 10.\n\nGUIDED REASONING (12 min)\n1. Solve x - 9 = -2, naming the inverse operation.\n2. Solve 4y + 6 = -10. Which operation comes first and why?\n3. A peer claims 5x = 20 gives x = 100. Explain the incorrect inverse and correct it.\n4. Solve (t/3) - 2 = 4. Check by substitution.\n\nINDEPENDENT PRACTICE (15 min)\nA. 7n - 3 = 25.\nB. -3m + 4 = 19.\nC. 5 + p/2 = -1.\nD. Translate and solve: A membership costs a $12 signup fee plus $6 for each visit. A total bill is $48. How many visits? Explain why visits must be a whole number here.\nE. Write a two-step equation with solution x = -4 and show a valid solution pathway.\n\nEXIT TICKET (10 min)\nSolve -4x + 7 = 23, label each equality-preserving operation and confirm your solution in the original equation.\n\nSELF-CHECK\nGuided: 1 = 7; 2 = -4; 4 = 18. Independent: A = 4; B = -5; C = -12; D = 6 visits. The exit ticket solution is x = -4. If a check fails, retrace the first transformation where equality stopped being preserved.","resources":[],"learningTargets":["I can solve one- and two-step equations, justify each transformation, and check solutions. Standards: HSA-REI.A.1, HSA-REI.B.3."],"standards":["A-REI.1","A-REI.3"],"estimatedMinutes":55,"activities":[{"id":"u01-d02-a1","kind":"launch","title":"Launch","estimatedMinutes":6,"evidence":"practice","instructions":"Essential question: Why does doing the same operation to both sides preserve equality?\n\nA balance scale holds a sealed bag and 7 blocks on the left, 19 blocks on the right. What is the mass of the bag in block units? Write b + 7 = 19. Explain what happens if we remove 7 blocks from both sides."},{"id":"u01-d02-a2","kind":"instruction","title":"Mini-Lesson","estimatedMinutes":12,"evidence":"practice","instructions":"An equation gives two equal quantities. Subtracting, adding, multiplying or dividing by the same nonzero quantity on both sides preserves the solution set. To isolate x in 3x + 5 = 20:\n1. Subtract 5 on each side: 3x = 15.\n2. Divide each side by 3: x = 5.\n3. Substitute into the original: 3(5) + 5 = 20. Both sides equal 20.\nA calculation without a check can conceal sign mistakes. In -2x - 6 = 10, add 6 then divide by -2 to get x = -8. Substitute: -2(-8) - 6 = 10."},{"id":"u01-d02-a3","kind":"guided_practice","title":"Guided Reasoning","estimatedMinutes":12,"evidence":"practice","instructions":"1. Solve x - 9 = -2, naming the inverse operation.\n2. Solve 4y + 6 = -10. Which operation comes first and why?\n3. A peer claims 5x = 20 gives x = 100. Explain the incorrect inverse and correct it.\n4. Solve (t/3) - 2 = 4. Check by substitution."},{"id":"u01-d02-a4","kind":"independent_practice","title":"Independent Practice","estimatedMinutes":15,"evidence":"practice","instructions":"A. 7n - 3 = 25.\nB. -3m + 4 = 19.\nC. 5 + p/2 = -1.\nD. Translate and solve: A membership costs a $12 signup fee plus $6 for each visit. A total bill is $48. How many visits? Explain why visits must be a whole number here.\nE. Write a two-step equation with solution x = -4 and show a valid solution pathway."},{"id":"u01-d02-a5","kind":"exit_ticket","title":"Exit Ticket","estimatedMinutes":10,"evidence":"teacher_review","instructions":"Solve -4x + 7 = 23, label each equality-preserving operation and confirm your solution in the original equation."},{"id":"u01-d02-a6","kind":"self_check","title":"Self-Check","evidence":"practice","instructions":"Guided: 1 = 7; 2 = -4; 4 = 18. Independent: A = 4; B = -5; C = -12; D = 6 visits. The exit ticket solution is x = -4. If a check fails, retrace the first transformation where equality stopped being preserved."}]},{"id":"u01-d03","title":"Day 3 · Distributive and Multi-Step Equations","body":"ALGEBRA I • UNIT 1 • DAY 3 OF 5 • 55 MINUTES\nEssential question: How can we solve equations that contain parentheses and variables on both sides?\nLearning targets: I can distribute, gather variable terms, detect contradictions and identities, and explain why an equation may have one, no, or infinitely many solutions. Standards: HSA-REI.A.1 and HSA-REI.B.3.\n\nWARM-UP (5 min)\nSimplify 2(3x - 4) and 4x + 2x - 8. Are they equivalent? What is the difference between simplifying an expression and solving an equation?\n\nTEACHING AND WORKED EXAMPLES (15 min)\nExample 1: 3(2x - 1) = x + 12.\nDistribute: 6x - 3 = x + 12.\nSubtract x: 5x - 3 = 12.\nAdd 3: 5x = 15.\nDivide by 5: x = 3.\nVerify: 3(6 - 1) = 15 and 3 + 12 = 15.\nExample 2: 2(x + 3) = 2x + 6. Distribute: 2x + 6 = 2x + 6. Every real x works, so infinitely many solutions.\nExample 3: 2(x + 3) = 2x + 5. Distribute and subtract 2x: 6 = 5. This is false, so there is no solution.\nA zero coefficient does not automatically mean x = 0; read the remaining statement.\n\nGUIDED WORK (10 min)\nA. Solve 4x + 9 = 2x - 3 and explain each step.\nB. Solve 5(y - 2) = 2y + 8.\nC. Classify 3(x + 2) = 3x + 7 without guessing a value.\nD. Classify 4(z - 1) = 4z - 4. Describe what the final statement means.\n\nINDEPENDENT PRACTICE (15 min)\n1. Solve 2(3p + 1) = 4p + 12 and check.\n2. Solve 7 - 2a = 3(a + 4).\n3. Classify 6(t + 1) - 2 = 6t + 4.\n4. Construct an equation that has no solution and one that has infinitely many; use the same variable on both sides.\n5. A student subtracts 3x from one side only in 5x + 4 = 3x + 10. Explain the error and give a correct solution.\n\nEXIT TICKET (10 min)\nClassify 5(x - 2) + 1 = 5x - 9 and solve 3(x + 4) = x - 2. Show reasoning, not just a final number.\n\nSELF-CHECK\nGuided: A = -6; B = 6; C no solution; D infinitely many solutions. Independent: 1 = 5; 2 = -1; 3 infinitely many. Exit: first equation is an identity; second solution x = -7. Seek help if you are unsure why 0 = 0 means every number works.","resources":[],"learningTargets":["I can distribute, gather variable terms, detect contradictions and identities, and explain why an equation may have one, no, or infinitely many solutions. Standards: HSA-REI.A.1 and HSA-REI.B.3."],"standards":["A-REI.1","A-REI.3"],"estimatedMinutes":55,"activities":[{"id":"u01-d03-a1","kind":"launch","title":"Warm-Up","estimatedMinutes":5,"evidence":"practice","instructions":"Essential question: How can we solve equations that contain parentheses and variables on both sides?\n\nSimplify 2(3x - 4) and 4x + 2x - 8. Are they equivalent? What is the difference between simplifying an expression and solving an equation?"},{"id":"u01-d03-a2","kind":"worked_example","title":"Teaching And Worked Examples","estimatedMinutes":15,"evidence":"practice","instructions":"Example 1: 3(2x - 1) = x + 12.\nDistribute: 6x - 3 = x + 12.\nSubtract x: 5x - 3 = 12.\nAdd 3: 5x = 15.\nDivide by 5: x = 3.\nVerify: 3(6 - 1) = 15 and 3 + 12 = 15.\nExample 2: 2(x + 3) = 2x + 6. Distribute: 2x + 6 = 2x + 6. Every real x works, so infinitely many solutions.\nExample 3: 2(x + 3) = 2x + 5. Distribute and subtract 2x: 6 = 5. This is false, so there is no solution.\nA zero coefficient does not automatically mean x = 0; read the remaining statement."},{"id":"u01-d03-a3","kind":"guided_practice","title":"Guided Work","estimatedMinutes":10,"evidence":"practice","instructions":"A. Solve 4x + 9 = 2x - 3 and explain each step.\nB. Solve 5(y - 2) = 2y + 8.\nC. Classify 3(x + 2) = 3x + 7 without guessing a value.\nD. Classify 4(z - 1) = 4z - 4. Describe what the final statement means."},{"id":"u01-d03-a4","kind":"independent_practice","title":"Independent Practice","estimatedMinutes":15,"evidence":"practice","instructions":"1. Solve 2(3p + 1) = 4p + 12 and check.\n2. Solve 7 - 2a = 3(a + 4).\n3. Classify 6(t + 1) - 2 = 6t + 4.\n4. Construct an equation that has no solution and one that has infinitely many; use the same variable on both sides.\n5. A student subtracts 3x from one side only in 5x + 4 = 3x + 10. Explain the error and give a correct solution."},{"id":"u01-d03-a5","kind":"exit_ticket","title":"Exit Ticket","estimatedMinutes":10,"evidence":"teacher_review","instructions":"Classify 5(x - 2) + 1 = 5x - 9 and solve 3(x + 4) = x - 2. Show reasoning, not just a final number."},{"id":"u01-d03-a6","kind":"self_check","title":"Self-Check","evidence":"practice","instructions":"Guided: A = -6; B = 6; C no solution; D infinitely many solutions. Independent: 1 = 5; 2 = -1; 3 infinitely many. Exit: first equation is an identity; second solution x = -7. Seek help if you are unsure why 0 = 0 means every number works."}]},{"id":"u01-d04","title":"Day 4 · Inequalities and Their Solution Sets","body":"ALGEBRA I • UNIT 1 • DAY 4 OF 5 • 55 MINUTES\nEssential question: How do inequalities describe ranges of possible answers?\nLearning targets: I can solve one-variable linear inequalities, reverse the comparison when multiplying or dividing by a negative, and represent solutions in words and on a number line. Standard: HSA-REI.B.3 and HSA-CED.A.1.\n\nCONTEXT (6 min)\nA club may spend at most $50. Room rental is $14 and each participant costs $4. Write 14 + 4n ≤ 50. What values of n make sense? Algebra says n ≤ 9; in this setting n is a nonnegative whole number.\n\nMINI-LESSON (12 min)\nAn inequality such as x < 7 describes many values. For x + 3 ≤ 8, subtract 3 from both sides: x ≤ 5. A number line uses a closed dot at 5 and shading to the left.\nCAUTION WITH NEGATIVES: Solve -3x > 12. Divide both sides by -3 AND reverse > to <: x < -4. Why? Multiplying an inequality by -1 reverses order: because 2 < 5, -2 > -5.\nCheck boundary and samples: x = -5 satisfies -3(-5) > 12, because 15 > 12. x = -3 does not.\n\nGUIDED PRACTICE (12 min)\n1. Solve 2x - 1 ≥ 9, and state if x = 5 is included.\n2. Solve -2y + 3 < 11, explaining the sign reversal.\n3. Describe an open dot at -1 shaded right using inequality symbols.\n4. Sketch the interval x ≥ -2 in words if a visual number line is unavailable.\n\nINDEPENDENT PRACTICE (15 min)\nA. 7 + 3t ≤ 22.\nB. -4n ≥ 16.\nC. 5 - 2p > 13.\nD. Write a real-life constraint using an inequality. Solve it and describe the domain (all reals, whole numbers, etc.).\nE. Error analysis: someone divides -2x < 8 by -2 and writes x < -4. Diagnose and correct the mistake.\n\nEXIT TICKET (10 min)\nSolve -5x + 2 ≥ 17. State if x = -3 is included. Explain one way an inequality differs from an equation.\n\nSELF-CHECK\nGuided 1: x ≥ 5, yes. 2: y > -4. 3: x > -1. Independent A: t ≤ 5; B: n ≤ -4; C: p < -4; E: x > -4. Exit: x ≤ -3, and -3 is included. If unsure about a boundary, substitute it into the original inequality.","resources":[],"learningTargets":["I can solve one-variable linear inequalities, reverse the comparison when multiplying or dividing by a negative, and represent solutions in words and on a number line. Standard: HSA-REI.B.3 and HSA-CED.A.1."],"standards":["A-REI.3","A-CED.1"],"estimatedMinutes":55,"activities":[{"id":"u01-d04-a1","kind":"launch","title":"Context","estimatedMinutes":6,"evidence":"practice","instructions":"Essential question: How do inequalities describe ranges of possible answers?\n\nA club may spend at most $50. Room rental is $14 and each participant costs $4. Write 14 + 4n ≤ 50. What values of n make sense? Algebra says n ≤ 9; in this setting n is a nonnegative whole number."},{"id":"u01-d04-a2","kind":"instruction","title":"Mini-Lesson","estimatedMinutes":12,"evidence":"practice","instructions":"An inequality such as x < 7 describes many values. For x + 3 ≤ 8, subtract 3 from both sides: x ≤ 5. A number line uses a closed dot at 5 and shading to the left.\nCAUTION WITH NEGATIVES: Solve -3x > 12. Divide both sides by -3 AND reverse > to <: x < -4. Why? Multiplying an inequality by -1 reverses order: because 2 < 5, -2 > -5.\nCheck boundary and samples: x = -5 satisfies -3(-5) > 12, because 15 > 12. x = -3 does not."},{"id":"u01-d04-a3","kind":"guided_practice","title":"Guided Practice","estimatedMinutes":12,"evidence":"practice","instructions":"1. Solve 2x - 1 ≥ 9, and state if x = 5 is included.\n2. Solve -2y + 3 < 11, explaining the sign reversal.\n3. Describe an open dot at -1 shaded right using inequality symbols.\n4. Sketch the interval x ≥ -2 in words if a visual number line is unavailable."},{"id":"u01-d04-a4","kind":"independent_practice","title":"Independent Practice","estimatedMinutes":15,"evidence":"practice","instructions":"A. 7 + 3t ≤ 22.\nB. -4n ≥ 16.\nC. 5 - 2p > 13.\nD. Write a real-life constraint using an inequality. Solve it and describe the domain (all reals, whole numbers, etc.).\nE. Error analysis: someone divides -2x < 8 by -2 and writes x < -4. Diagnose and correct the mistake."},{"id":"u01-d04-a5","kind":"exit_ticket","title":"Exit Ticket","estimatedMinutes":10,"evidence":"teacher_review","instructions":"Solve -5x + 2 ≥ 17. State if x = -3 is included. Explain one way an inequality differs from an equation."},{"id":"u01-d04-a6","kind":"self_check","title":"Self-Check","evidence":"practice","instructions":"Guided 1: x ≥ 5, yes. 2: y > -4. 3: x > -1. Independent A: t ≤ 5; B: n ≤ -4; C: p < -4; E: x > -4. Exit: x ≤ -3, and -3 is included. If unsure about a boundary, substitute it into the original inequality."}]},{"id":"u01-d05","title":"Day 5 · Modeling and Evidence of Mastery","body":"ALGEBRA I • UNIT 1 • DAY 5 OF 5 • 55 MINUTES\nEssential question: How do we translate an unfamiliar situation into an equation or inequality and defend the answer?\nLearning targets: I can define variables, create a linear equation or inequality from a context, solve accurately, check feasibility, and explain my reasoning. Standards: HSA-CED.A.1, HSA-REI.A.1, HSA-REI.B.3.\n\nLAUNCH (5 min)\nA school has $150 for an after-school science event. The venue charges $30 and each lab kit costs $8. Write an equation to find exactly how many kits $150 buys, then determine how many kits are affordable if spending must stay at or below $150. Is it possible to buy half a kit?\n\nWORKED MODEL (12 min)\nLet k be the number of kits. Define k as a nonnegative integer.\nBudget model: 30 + 8k ≤ 150.\nSubtract 30: 8k ≤ 120.\nDivide by 8: k ≤ 15.\nConclusion: The school can purchase at most 15 kits. Check: 30 + 8(15) = 150. If k = 16, cost would be $158, too high. The domain matters: negative or fractional numbers of kits are not permitted.\n\nGUIDED TRANSFER (12 min)\n1. A student has $42 and wants notebooks at $5 each after paying a $7 delivery charge. Model, solve and interpret.\n2. A subscription costs $11 plus $3 for each extra class. Total charged is $29. Model and solve.\n3. A museum ticket costs $9 and 5 tickets cost $45. Is 5(9) = 45 an expression or equation? Explain.\n\nINDEPENDENT PRACTICE (15 min)\nA. Create an equation from: four times a number minus 7 equals 29. Solve and check.\nB. Create an inequality from: at least 20 minutes of exercise have been completed, and every round adds 6 minutes, starting from 8 minutes. Find the minimum whole number of rounds needed.\nC. Invent a school-business constraint using a fixed fee and per-student cost. Define variables, solve and critique one assumption in your model.\nD. Explain why an accurate algebraic solution sometimes needs to be rounded down and sometimes up based on context.\n\nUNIT REFLECTION AND NEXT STEPS (11 min)\nReview your work from Days 1–4. Identify a strength and an error you corrected. Complete the Unit 1 Checkpoint assignment in your class''s Assignments view. Attach no personal information in mathematical examples. The checkpoint is scored by your teacher; clicking ''Mark lesson complete'' records instructional progress but does not confer academic credit.\n\nSELF-CHECK\nGuided 1: 7 + 5n ≤ 42, so n ≤ 7 whole notebooks. 2: 11 + 3c = 29, c = 6. Independent A: n = 9. B: 8 + 6r ≥ 20 gives r ≥ 2. For C, check whether the cost rule is realistic and whether quantities must be whole numbers.","resources":[],"learningTargets":["I can define variables, create a linear equation or inequality from a context, solve accurately, check feasibility, and explain my reasoning. Standards: HSA-CED.A.1, HSA-REI.A.1, HSA-REI.B.3."],"standards":["A-CED.1","A-REI.1","A-REI.3"],"estimatedMinutes":55,"activities":[{"id":"u01-d05-a1","kind":"launch","title":"Launch","estimatedMinutes":5,"evidence":"practice","instructions":"Essential question: How do we translate an unfamiliar situation into an equation or inequality and defend the answer?\n\nA school has $150 for an after-school science event. The venue charges $30 and each lab kit costs $8. Write an equation to find exactly how many kits $150 buys, then determine how many kits are affordable if spending must stay at or below $150. Is it possible to buy half a kit?"},{"id":"u01-d05-a2","kind":"worked_example","title":"Worked Model","estimatedMinutes":12,"evidence":"practice","instructions":"Let k be the number of kits. Define k as a nonnegative integer.\nBudget model: 30 + 8k ≤ 150.\nSubtract 30: 8k ≤ 120.\nDivide by 8: k ≤ 15.\nConclusion: The school can purchase at most 15 kits. Check: 30 + 8(15) = 150. If k = 16, cost would be $158, too high. The domain matters: negative or fractional numbers of kits are not permitted."},{"id":"u01-d05-a3","kind":"guided_practice","title":"Guided Transfer","estimatedMinutes":12,"evidence":"practice","instructions":"1. A student has $42 and wants notebooks at $5 each after paying a $7 delivery charge. Model, solve and interpret.\n2. A subscription costs $11 plus $3 for each extra class. Total charged is $29. Model and solve.\n3. A museum ticket costs $9 and 5 tickets cost $45. Is 5(9) = 45 an expression or equation? Explain."},{"id":"u01-d05-a4","kind":"independent_practice","title":"Independent Practice","estimatedMinutes":15,"evidence":"practice","instructions":"A. Create an equation from: four times a number minus 7 equals 29. Solve and check.\nB. Create an inequality from: at least 20 minutes of exercise have been completed, and every round adds 6 minutes, starting from 8 minutes. Find the minimum whole number of rounds needed.\nC. Invent a school-business constraint using a fixed fee and per-student cost. Define variables, solve and critique one assumption in your model.\nD. Explain why an accurate algebraic solution sometimes needs to be rounded down and sometimes up based on context."},{"id":"u01-d05-a5","kind":"reflection","title":"Unit Reflection And Next Steps","estimatedMinutes":11,"evidence":"practice","instructions":"Review your work from Days 1–4. Identify a strength and an error you corrected. Complete the Unit 1 Checkpoint assignment in your class''s Assignments view. Attach no personal information in mathematical examples. The checkpoint is scored by your teacher; clicking ''Mark lesson complete'' records instructional progress but does not confer academic credit."},{"id":"u01-d05-a6","kind":"self_check","title":"Self-Check","evidence":"practice","instructions":"Guided 1: 7 + 5n ≤ 42, so n ≤ 7 whole notebooks. 2: 11 + 3c = 29, c = 6. Independent A: n = 9. B: 8 + 6r ≥ 20 gives r ≥ 2. For C, check whether the cost rule is realistic and whether quantities must be whole numbers."}]}]}'::jsonb),true),'{learning,syllabus}',to_jsonb('CAN Algebra I (synthetic instructional pilot). Keep original Foundations preview for continuity. Unit 1, Week 1 comprises five 55-minute lessons and two teacher-graded assignments. This is a partial course and cannot award high-school graduation credit until a complete standards-aligned year, qualified instruction, assessments, and school approval are verified.'::text),true),'{learning,blueprint}','{"schemaVersion":1,"courseCode":"CAN-ALG1","title":"CAN Algebra I | 36-week curriculum development blueprint","targetInstructionalWeeks":36,"reviewStatus":"planning","creditStatus":"not_credit_ready","scopeNote":"A provisional teaching sequence, not a school-approved course of study. All standards, lesson content, assessments, instructional time, support plans and graduation or UC A-G course recognition require qualified educator and school review. The 165-hour estimate assumes 36x5x55-minute sessions and is not evidence of delivered instruction.","standardsAuthorityUrl":"https://www.cde.ca.gov/be/st/ss/mathstandard.asp","weeks":[{"week":1,"unitId":"algebra1-u01","title":"Expressions, equations and inequality foundations","focus":"Distinguish expressions, justify equation-solving steps, solve and interpret basic inequalities.","standards":["A-SSE.1","A-CED.1","A-REI.1","A-REI.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"authored"},{"week":2,"unitId":"algebra1-u01","title":"Multi-step equations and formulas","focus":"Solve literal and multi-step linear equations and justify transformations in contextual formulas.","standards":["A-CED.4","A-REI.1","A-REI.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":3,"unitId":"algebra1-u01","title":"Linear problem solving and constraints","focus":"Represent contextual quantities, units, bounds and inequalities in a mathematically justified model.","standards":["N-Q.1","A-CED.1","A-REI.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":4,"unitId":"algebra1-u01","title":"Unit 1 cumulative assessment and reteaching","focus":"Demonstrate algebraic fluency and modeling with a scored checkpoint and targeted reassessment.","standards":["A-SSE.1","A-CED.1","A-REI.1","A-REI.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":5,"unitId":"algebra1-u02","title":"Functions, inputs, outputs and domains","focus":"Interpret functions as relationships, evaluate notation and select sensible input domains.","standards":["F-IF.1","F-IF.2"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":6,"unitId":"algebra1-u02","title":"Tables, graphs and multiple representations","focus":"Connect function tables, graphs and verbal descriptions and interpret key features.","standards":["F-IF.4","F-IF.5"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":7,"unitId":"algebra1-u02","title":"Average rate of change","focus":"Calculate and explain changing quantities using function representations and units.","standards":["F-IF.6","F-LE.1"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":8,"unitId":"algebra1-u02","title":"Functions unit review and transfer","focus":"Compare representations and communicate domain, range and rate evidence on an assessed task.","standards":["F-IF.1","F-IF.4","F-IF.6"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":9,"unitId":"algebra1-u03","title":"Slope and linear equations","focus":"Find rate of change from graphs, tables and contexts; distinguish slope from initial value.","standards":["F-LE.1","F-IF.6","A-CED.2"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":10,"unitId":"algebra1-u03","title":"Equivalent linear forms and graphing","focus":"Move among slope-intercept, point-slope and standard forms to graph relationships.","standards":["A-CED.2","A-REI.10"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":11,"unitId":"algebra1-u03","title":"Fitting and interpreting linear models","focus":"Choose useful linear models for data and explain reasonable errors and constraints.","standards":["S-ID.6","S-ID.7","S-ID.8"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":12,"unitId":"algebra1-u03","title":"Linear model design challenge","focus":"Build, critique and present a contextual linear model with teacher-reviewed evidence.","standards":["A-CED.2","S-ID.6","F-IF.6"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":13,"unitId":"algebra1-u04","title":"Systems by graphing","focus":"Interpret the intersection of two linear functions as a solution to two constraints.","standards":["A-REI.6","A-REI.11"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":14,"unitId":"algebra1-u04","title":"Systems by substitution","focus":"Solve systems symbolically and verify ordered pairs in both original equations.","standards":["A-REI.6"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":15,"unitId":"algebra1-u04","title":"Systems by elimination","focus":"Select a solution strategy, handle no/infinitely many solutions and explain meaning.","standards":["A-REI.6"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":16,"unitId":"algebra1-u04","title":"Systems application and assessment","focus":"Model pricing and supply constraints using systems and communicate solutions.","standards":["A-CED.3","A-REI.6","A-REI.12"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":17,"unitId":"algebra1-u05","title":"Integer exponents and growth","focus":"Apply exponent properties and explain multiplicative rather than additive change.","standards":["N-RN.1","A-SSE.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":18,"unitId":"algebra1-u05","title":"Arithmetic and geometric patterns","focus":"Identify recursive and explicit sequence rules and relate patterns to functions.","standards":["F-BF.2","F-LE.2"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":19,"unitId":"algebra1-u05","title":"Exponential functions","focus":"Build growth and decay models and interpret initial values and growth factors.","standards":["F-LE.1","F-LE.2","F-LE.5"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":20,"unitId":"algebra1-u05","title":"Linear and exponential comparison","focus":"Select models from data, critique extrapolation and complete a scored model comparison.","standards":["F-LE.3","F-LE.5"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":21,"unitId":"algebra1-u06","title":"Polynomial operations","focus":"Add, subtract and multiply polynomials, attending to structure and the distributive property.","standards":["A-APR.1","A-SSE.1"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":22,"unitId":"algebra1-u06","title":"Factoring quadratic expressions","focus":"Use factoring to express equivalent quadratics and interpret zero-product solutions.","standards":["A-SSE.3","A-REI.4"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":23,"unitId":"algebra1-u06","title":"Quadratic identities and structure","focus":"Relate equivalent polynomial forms and identify why each is useful.","standards":["A-SSE.2","A-SSE.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":24,"unitId":"algebra1-u06","title":"Polynomials unit mastery and reteaching","focus":"Demonstrate polynomial operations and factoring on assessed problems with error analysis.","standards":["A-APR.1","A-SSE.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":25,"unitId":"algebra1-u07","title":"Graphs of quadratic functions","focus":"Interpret vertex, zeros, symmetry and direction of quadratic graphs in context.","standards":["F-IF.4","F-IF.7"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":26,"unitId":"algebra1-u07","title":"Finding roots by factoring","focus":"Solve quadratic equations using factoring and check solutions.","standards":["A-REI.4","F-IF.8"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":27,"unitId":"algebra1-u07","title":"Complete the square and quadratic formula","focus":"Select symbolic quadratic solution methods and explain roots in different cases.","standards":["A-REI.4","A-SSE.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":28,"unitId":"algebra1-u07","title":"Quadratic model investigations","focus":"Fit and critique quadratic situations and communicate vertex and intercept meaning.","standards":["A-CED.2","F-IF.4","F-IF.7"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":29,"unitId":"algebra1-u08","title":"Square roots and real-number structure","focus":"Reason about radicals, square-root values and when solutions are real.","standards":["N-RN.2","A-REI.4"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":30,"unitId":"algebra1-u08","title":"Quadratic equations in context","focus":"Translate measurement or motion contexts into solvable quadratic equations.","standards":["A-CED.1","A-REI.4"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":31,"unitId":"algebra1-u08","title":"Transformations and function comparison","focus":"Compare function transformations and explain changing parameters.","standards":["F-BF.3","F-IF.9"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":32,"unitId":"algebra1-u08","title":"Nonlinear unit assessment","focus":"Demonstrate method selection and interpretation on a teacher-scored transfer task.","standards":["F-IF.7","A-REI.4","F-BF.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":33,"unitId":"algebra1-u09","title":"Describing one-variable data","focus":"Represent distributions and explain center, variability and outliers.","standards":["S-ID.1","S-ID.2","S-ID.3"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":34,"unitId":"algebra1-u09","title":"Bivariate data and residuals","focus":"Fit lines to scatterplots, evaluate residuals and critique data collection.","standards":["S-ID.6","S-ID.7","S-ID.8"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":35,"unitId":"algebra1-u09","title":"Course synthesis capstone","focus":"Model a real question using functions, equations and data with a documented source.","standards":["A-CED.1","F-IF.6","S-ID.6"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":2,"status":"planned"},{"week":36,"unitId":"algebra1-u09","title":"Final assessment and targeted reassessment","focus":"Complete the cumulative Algebra I assessment, teacher feedback, reflection and interventions.","standards":["A-REI.3","A-REI.6","F-IF.4","A-REI.4","S-ID.6"],"plannedInstructionalDays":5,"estimatedMinutesPerDay":55,"plannedAssessmentCount":3,"status":"planned"}]}'::jsonb,true) || jsonb_build_object('unitReadiness','{"readiness":"teacher_review_required","unitId":"algebra1-u01","standards":["CCSS.HSA-SSE.A.1","CCSS.HSA-CED.A.1","CCSS.HSA-REI.A.1","CCSS.HSA-REI.B.3"],"instructionalDays":5,"suggestedMinutesPerDay":55,"source":"can-original","creditPolicy":"pending school approval; this week alone carries no course credit"}'::jsonb,'sourceVersionId',v.id::text,'teacherGuides','{"version":1,"courseCode":"CAN-ALG1","visibility":"teacher_only","units":[{"unitId":"algebra1-u01","reviewStatus":"draft","teacherOverview":"Five 55-minute Algebra I lessons introducing equivalence, solving equations, classifying solution sets, inequalities and applied modeling. Review the student''s work for written mathematical reasoning, not only final numerical answers. The unit and guide require qualified mathematics teacher review before school approval.","lessons":[{"lessonId":"u01-d01","preparation":"Diagnose arithmetic with negative integers and the distributive property. Prepare paired equivalent and non-equivalent expression examples. Model substitution carefully, including parentheses around negative inputs.","workedAnswers":[{"prompt":"Guided: evaluate 2a+3b at a=-2, b=5.","answer":"Substitute 2(-2)+3(5)=-4+15=11. A student must show the substituted expression, not only the final value."},{"prompt":"Independent: evaluate 3x²-2x at x=-2.","answer":"3(-2)²-2(-2)=3(4)+4=16. The square acts on the negative base in parentheses."},{"prompt":"Independent: simplify 3(2p-5)+4p.","answer":"6p-15+4p=10p-15. Check by substitution at p=1: -5 on both sides."},{"prompt":"Exit ticket: simplify 2(3k-4)+k.","answer":"6k-8+k=7k-8. An expression has no equality assertion; an equation asserts equality between two quantities."}],"misconceptions":["A learner may combine unlike terms such as 4x+4 into 8x; ask whether variable and constant quantities can be added as like terms.","A learner may distribute multiplication to the first term only. Represent 2(x+5) as two groups of x+5 and expand to 2x+10.","A learner may mis-evaluate a negative substitution. Require explicit parentheses around negative numbers before applying exponents."],"interventions":["For difficulty combining terms, use algebra tiles or matched-colored variable/constant tokens, then write the corresponding symbolic statement.","Have students evaluate their claimed equivalents at two contrasting inputs and explain why numerical checks support but do not prove equivalence.","Provide a short sign-rule warm-up if the learner cannot substitute a negative input reliably."],"extensions":["Create three distinct expressions equivalent to 4(x-2)+3x and justify the transformations without numerical substitutions."]},{"lessonId":"u01-d02","preparation":"Prepare a physical or virtual balance scale model and emphasize operations applied symmetrically to both sides. Require substitution checks before accepting solutions.","workedAnswers":[{"prompt":"Guided: solve x-9=-2.","answer":"Add 9 to both sides to obtain x=7. Check 7-9=-2."},{"prompt":"Guided: solve 4y+6=-10.","answer":"Subtract 6, then divide by 4: 4y=-16, y=-4. Check 4(-4)+6=-10."},{"prompt":"Independent: solve 7n-3=25.","answer":"Add 3, divide by 7: 7n=28, n=4. Substitute to verify."},{"prompt":"Independent: solve -3m+4=19.","answer":"Subtract 4, divide by -3: -3m=15, m=-5. Check -3(-5)+4=19."},{"prompt":"Exit ticket: solve -4x+7=23.","answer":"Subtract 7: -4x=16; divide by -4: x=-4; check -4(-4)+7=23."}],"misconceptions":["Some students multiply rather than divide to undo a coefficient. Ask which operation reverses multiplication and why.","Students may divide only one term on one side; use balance drawings to stress maintaining equality.","Students may produce x=4 for -4x=16; request an original-equation check."],"interventions":["Use color-coded two-column equality transformations, recording an operation in both columns.","Assign paired problems with positive and negative coefficients; ask the learner to predict the sign before solving.","Allow a calculator only for arithmetic checking after an algebraic solution has been justified."],"extensions":["Write two different equations with solution x=-6, each with at least two steps, and explain which solution strategy is more efficient."]},{"lessonId":"u01-d03","preparation":"Prepare identity and contradiction examples in addition to unique-solution equations. Avoid teaching zero coefficient as implying x=0.","workedAnswers":[{"prompt":"Worked: solve 3(2x-1)=x+12.","answer":"Distribute: 6x-3=x+12. Subtract x and add 3: 5x=15. Divide by 5: x=3. Both original sides equal 15."},{"prompt":"Guided: solve 4x+9=2x-3.","answer":"Subtract 2x and then 9: 2x=-12, so x=-6. Check -24+9=-15 and -12-3=-15."},{"prompt":"Guided: solve 5(y-2)=2y+8.","answer":"5y-10=2y+8; subtract 2y and add 10 to get 3y=18; y=6."},{"prompt":"Independent: classify 6(t+1)-2=6t+4.","answer":"Distribution yields 6t+4=6t+4, an identity true for every real t; infinitely many solutions."},{"prompt":"Exit ticket: solve 3(x+4)=x-2.","answer":"Distribute: 3x+12=x-2. Subtract x, then subtract 12: 2x=-14, so x=-7. Check original: 3(-7+4)=3(-3)=-9 and -7-2=-9."}],"misconceptions":["Learners may interpret a statement 0=0 as x=0; emphasize it holds for any real variable value.","A false final statement such as 6=5 means no value solves the original equation, not that a step was necessarily performed incorrectly.","Learners may change signs while moving variable terms; write the same subtraction explicitly on both sides."],"interventions":["Sort six equations into one, no, or infinitely many solutions based on their simplified final statements.","Use algebra tiles to pair and remove equal variable groups on both sides.","Have a learner test two distinct inputs for a proposed identity and then establish equivalence symbolically."],"extensions":["Construct an identity and a contradiction by changing only the constant in a two-sided linear equation."]},{"lessonId":"u01-d04","preparation":"Prepare a horizontal number line with labeled endpoints and a nonvisual verbal alternative. Demonstrate multiplication by negative one as reversing order.","workedAnswers":[{"prompt":"Guided: solve 2x-1≥9.","answer":"Add 1, divide by 2: x≥5. A closed dot at 5 shaded right; x=5 is included."},{"prompt":"Guided: solve -2y+3<11.","answer":"Subtract 3: -2y<8. Divide by -2 and reverse the sign: y>-4."},{"prompt":"Independent: solve -4n≥16.","answer":"Divide by -4 and reverse the inequality: n≤-4. Check n=-5 satisfies -4(-5)≥16."},{"prompt":"Exit ticket: solve -5x+2≥17.","answer":"Subtract 2 to get -5x≥15; divide by -5, reverse ≥ to ≤: x≤-3; -3 is included."}],"misconceptions":["Learners may forget that dividing by a negative reverses the comparison sign.","Learners may use an open boundary for ≤ or ≥; ask whether the boundary value itself satisfies the original inequality.","Learners may accept fractional or negative counts of people in a context; explicitly define the permissible domain."],"interventions":["Use two test values around a boundary to check shading direction.","Provide paired inequalities 3x>9 and -3x>9 to compare operations and solutions.","Describe open and closed endpoints aloud for accessible practice."],"extensions":["Construct two inequalities with the same solution set but different coefficients and prove they are equivalent."]},{"lessonId":"u01-d05","preparation":"Model units and domain restrictions with a real classroom budget. Explain that lesson completion is not a score and direct students to their separate assessments.","workedAnswers":[{"prompt":"Launch: maximum number of $8 kits after a $30 fixed cost with $150 budget.","answer":"30+8k≤150 implies 8k≤120, k≤15; since k is a nonnegative integer, the maximum is 15 kits."},{"prompt":"Guided: $42 total, $7 delivery, $5 notebooks.","answer":"7+5n≤42 yields n≤7 nonnegative whole notebooks; n=7 gives exactly $42."},{"prompt":"Guided: $11 fee plus $3 per class totals $29.","answer":"11+3c=29; c=6 classes. Check 11+18=29."},{"prompt":"Independent: at least 20 exercise minutes starting at 8 minutes and adding 6 per round.","answer":"8+6r≥20 gives r≥2. Two full rounds are needed."}],"misconceptions":["A learner may round contextual counts the wrong direction. Ask whether the task requires a minimum or maximum and verify the rounded integer.","A learner may confuse revenue with net proceeds. Have them label the original total and subtract startup costs explicitly.","A learner may express a feasible negative number of kits. Define units and a nonnegative integer domain before solving."],"interventions":["Use a table of 0, 1, 2, ... units to compare the symbolic result with actual costs.","Require verbal definitions of every symbol and unit before any equation manipulation.","Use a quick substitution check at the chosen count and one count beyond the proposed feasible boundary."],"extensions":["Compare two vendors with different fixed fees and per-student costs and determine when each becomes less expensive."]}],"assessments":[{"assessmentKey":"u01-formative","title":"Algebra I · Unit 1 Guided Problem Set","answerGuide":[{"item":"1","correctResponse":"4(2x-3)-(x+5)=8x-12-x-5=7x-17.","evidenceToLookFor":"Distribution over all terms and correct subtraction of the entire second parenthesis."},{"item":"2","correctResponse":"3(2x-1)=x+12 gives 6x-3=x+12, then 5x=15, x=3; both sides equal 15.","evidenceToLookFor":"Same operations on both sides and substitution in the original equation."},{"item":"3","correctResponse":"-2y+3<11 gives -2y<8, so y>-4 after reversing the inequality on division by -2.","evidenceToLookFor":"Explicit explanation of reversal of ordering by division by a negative."},{"item":"4","correctResponse":"90+15s=285 gives 15s=195, s=13 students. The result is a nonnegative whole number, and 90+195=285.","evidenceToLookFor":"Variable definition, equation, solution, units, and validity check."}],"scoringNotes":"Apply the existing 20-point rubric, not points invented by this answer guide. Award evidence for variable definition (6 points), justified solution steps (8 points), and checking and interpretation (6 points); comment on individual inaccuracies and invite revisions."},{"assessmentKey":"u01-checkpoint","title":"Algebra I · Unit 1 Mastery Checkpoint","answerGuide":[{"item":"1","correctResponse":"3(2a-5)+4a=6a-15+4a=10a-15. For a=2: 20-15=5. Original: 3(4-5)+8=5.","evidenceToLookFor":"Equivalent expression and evaluation of both original and simplified forms."},{"item":"2","correctResponse":"5(2x-1)=3x+16 gives 10x-5=3x+16, hence 7x=21, x=3. Check 5(6-1)=25 and 9+16=25.","evidenceToLookFor":"Justified inverse operations and original-equation check."},{"item":"3A","correctResponse":"4(y+2)=4y+8 is an identity. Every real y satisfies it.","evidenceToLookFor":"Explanation that simplifying yields the same expression on both sides."},{"item":"3B","correctResponse":"3(z+2)=3z+5 simplifies to 3z+6=3z+5, then 6=5. There is no solution.","evidenceToLookFor":"Recognition of a contradiction, not a proposed value."},{"item":"4","correctResponse":"-4t+7≥19 gives -4t≥12, then t≤-3 after reversing the inequality. The boundary -3 is included.","evidenceToLookFor":"Correct inequality reversal, boundary decision and explanation."},{"item":"5","correctResponse":"Let n be nonnegative integer notebooks. Net revenue after fees is 7n-25. Solve 7n-25≥200, giving n≥225/7≈32.143, so the minimum integer count is n=33. Check 7·33-25=206≥200, while n=32 gives 199<200.","evidenceToLookFor":"Explicit net-versus-gross distinction, variable/domain, inequality, round up and checks at 32 and 33."}],"scoringNotes":"Use the existing 30-point rubric: expressions 5, equations 10, inequalities 10 and modeling/communication 5. Consider independent reasoning, use feedback on misconceptions, and permit a new supervised demonstration of mastery where school policy allows."}]}]}'::jsonb),
now()
